keyConcepts.codeExample:
record Invoice(String customer, List<Item> items) {
    Invoice {
        items = List.copyOf(items); // copie défensive et immuable
    }
}

List<Item> mutable = new ArrayList<>(List.of(new Item("Licence", 100)));
Invoice invoice = new Invoice("Ada", mutable);
mutable.add(new Item("Support", 50)); // n'affecte plus invoice.items()

